38			t.Fatal(err)
39		}
40		if err := e.StartTradingDay(1, lossLimit); err != nil {
41			t.Fatal(err)
42		}
43		mustQuote(t, e, "A", Quote{Seq: 2, Moment: 2, Price: 5}, 1) // 净值 950，亏损 50
44		if e.RiskStatus().Baseline != 1000 || e.RiskStatus().Equity != 950 ||
45			e.RiskStatus().Loss != 50 || e.RiskStatus().Restricted {
