231	// TestRiskPartialBuyFillBelowLimitKeepsRemainderAndReserve 覆盖未触线路径：
232	// 成交后亏损仍低于上限时只完成部分成交，剩余买单与现金占用继续有效，
233	// 不产生触线或撤销记录。
234	func TestRiskPartialBuyFillBelowLimitKeepsRemainderAndReserve(t *testing.T) {
235		e, bid := riskTradeSetup(t, 100)
236	
237		// 仅成交 2 股 @20：现金 860、持仓 12，净值 860+60=920、亏损 80 < 100。
238		recsBefore := len(e.Records())
239		res, err := e.Fill(Trade{TradeID: 2, OrderID: bid, Symbol: "A", Side: Buy, Price: 20, Qty: 2})
240		if err != nil {
241			t.Fatalf("成交必须成功: %v", err)
242		}
243		if res != (FillResult{TradeID: 2, OrderID: bid, Price: 20, Qty: 2,
244			Filled: 2, Remaining: 8, Status: StatusPartial}) {
245			t.Fatalf("成交结果应为累计 2、剩余 8、部分成交: %+v", res)
246		}
247	
248		st := e.RiskStatus()
249		if st.Restricted || st.Equity != 920 || st.Loss != 80 {
250			t.Fatalf("亏损 80 未达上限 100，不应触线: %+v", st)
251		}
252	
253		// 订单仍为部分成交、剩余 8 股有效；剩余占用 8×20=160 继续保留。
254		o, _ := e.Order(bid)
255		if o.Status != StatusPartial || o.Filled != 2 || o.Qty != 10 || o.Remaining() != 8 || o.Reason != "" {
256			t.Fatalf("未触线时剩余买单必须继续有效: %+v", o)
257		}
258		if e.Cash() != 860 || e.ReservedCash() != 160 || e.AvailableCash() != 700 || e.Position("A") != 12 {
259			t.Fatalf("剩余 8 股的现金占用 160 必须继续保留: cash=%d reserved=%d available=%d pos=%d",
260				e.Cash(), e.ReservedCash(), e.AvailableCash(), e.Position("A"))
261		}
262	
263		// 只新增一条成交记录，不得有触线或撤销记录。
264		recs := e.Records()[recsBefore:]
265		if len(recs) != 1 || recs[0].Kind != RecordFilled {
266			t.Fatalf("未触线时只能新增一条成交记录，实际 %+v", recs)
267		}
268		if countRiskRecords(e) != 0 {
269			t.Fatal("未达上限不得产生触线记录")
270		}
271	
272		// 剩余部分仍可继续成交（占用有效）：再成交 8 股后订单全部成交。
273		res2, err := e.Fill(Trade{TradeID: 3, OrderID: bid, Symbol: "A", Side: Buy, Price: 20, Qty: 8})
274		if err != nil {
275			t.Fatalf("保留的剩余 8 股必须仍可成交: %v", err)
276		}
