	mustSetMax(t, e, "A", 100)
	mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: price}, 1)
	id := mustBuy(t, e, "A", 10, price)
	if _, err := e.Fill(Trade{TradeID: 1, OrderID: id, Symbol: "A", Side: Buy, Price: price, Qty: 10}); err != nil {
		t.Fatal(err)
	}
	return e
}

